 "content": "def transform(grid):
    """Repeat the distinctive shape from the grid, recolored by each row's key tile."""
    h, w = len(grid), len(grid[0])
    # Find full-width/full-height separator lines (the grid frame color).
    sep = None
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1 and next(iter(vals)) != 0:
            sep = next(iter(vals))
            break
    if sep is None:
        raise ValueError('no horizontal separator')
    rs = [r for r in range(h) if all(v == sep for v in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    rbounds = [-1] + rs + [h]
    cbounds = [-1] + cs + [w]
    # Cell interiors are the areas between separator lines.
    cells = [[(rbounds[i]+1, rbounds[i+1], cbounds[j]+1, cbounds[j+1])
              for j in range(len(cbounds)-1)] for i in range(len(rbounds)-1)]
    # First column contains one solid key-color patch per row.
    keys = []
    for r0, r1, c0, c1 in (row[0] for row in cells):
        counts = {}
        for r in range(r0, r1):
            for c in range(c0, c1):
                v = grid[r][c]
                if v not in (0, sep):
                    counts[v] = counts.get(v, 0) + 1
        if not counts:
            raise ValueError('missing row key')
        keys.append(max(counts, key=counts.get))
    # The distinctive shape is the sole non-key object in the other cells.
    candidates = []
    for i, row in enumerate(cells):
        for j, (r0, r1, c0, c1) in enumerate(row):
            if j == 0:
                continue
            found = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)]
            if found:
                candidates.append((found, r1-r0, c1-c0))
    if not candidates:
        raise ValueError('missing template')
    # Use the most populated non-key cell as the template.
    shape, cell_h, cell_w = max(candidates, key=lambda x: len(x[0]))
    offsets = [(r, c) for r, c, _ in shape]
    out = [row[:] for row in grid]
    for i, row in enumerate(cells):
        for j, (r0, r1, c0, c1) in enumerate(row):
            if j == 0:
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in offsets:
                out[r0+dr][c0+dc] = keys[i]
    return out
